// Generate the Aumlok approval fixtures from GENESIS's own contract code.
//
//   node tests/aumlok-approval/make-fixtures.mjs --genesis <checkout> --out <dir>
//
// WHAT IS GENESIS'S AND WHAT IS THIS SCRIPT'S. The signed bytes come from Genesis's own
// `approvalSigningBytes` and the response record from `createSignedApprovalResponse`; the request
// record is built and validated by Genesis's `createApprovalRequest`. This script only supplies the
// facts and a standard Ed25519 signature over those exact bytes (node:crypto). It does not call
// `createOwnerSigner`, whose call shape is part of the signer channel this fixture does not need —
// recorded here rather than implied.
//
// KEYS ARE DISPOSABLE AND PUBLIC. Both keypairs are generated per run and written out: they are
// test keys with no custody, and nothing in Diamond trusts them.
import { createApprovalRequest, approvalSigningBytes, createSignedApprovalResponse,
         createRefusedApprovalResponse, APPROVAL_REQUEST_DOMAIN } from "/tmp/gen2/plugins/aukora-aumlok/lib/owner-approval.mjs";
import { generateKeyPairSync, createHash, sign as nodeSign } from "node:crypto";
import { writeFileSync, mkdirSync } from "node:fs";
import { join } from "node:path";

const argv = process.argv.slice(2);
const arg = (name) => { const i = argv.indexOf(name); return i < 0 ? null : argv[i + 1]; };
const OUT = arg("--out");
mkdirSync(OUT, { recursive: true });

const keypair = () => {
  const { publicKey, privateKey } = generateKeyPairSync("ed25519");
  const raw = Buffer.from(publicKey.export({ format: "jwk" }).x, "base64url");
  return { privateKey, pkHex: raw.toString("hex") };
};
const A = keypair();   // the anchor
const B = keypair();   // a DIFFERENT, independently supplied anchor (the wrong-anchor control)
writeFileSync(join(OUT, "anchor-a.pk"), A.pkHex + "\n");
writeFileSync(join(OUT, "anchor-b.pk"), B.pkHex + "\n");
// The private keys are NEVER written: only the public anchors are fixtures. Regenerating the
// fixtures mints fresh disposable keys, which is the point of them being disposable.

const base = {                          // the facts of ONE memory operation
  subject: "aukora:1:" + "55".repeat(32),
  activeControlDigest: "11".repeat(32),
  operationDigest: "22".repeat(32),
  challenge: "33".repeat(32),
  issuedAt: 1789000000,
  expiresAt: 1789000600,
};
const request = createApprovalRequest(base);                       // Genesis's closed record
const preimage = approvalSigningBytes(request);                    // Genesis's exact signed bytes
const signatureA = nodeSign(null, preimage, A.privateKey).toString("hex");

const honest = {
  request,
  response: createSignedApprovalResponse({ challenge: request.challenge, signature: signatureA }),
};
const write = (name, doc) => {
  writeFileSync(join(OUT, name), JSON.stringify(doc, null, 2) + "\n");
  return createHash("sha256").update(JSON.stringify(doc)).digest("hex");
};

const digests = {
  honest: write("honest.json", honest),
  // the SAME bytes and signature, with one signed field changed afterwards
  "changed-field": write("changed-field.json",
    { request: { ...request, issuedAt: request.issuedAt + 1 }, response: honest.response }),
  // a signature that is not this key's
  forged: write("forged.json",
    { request, response: { ...honest.response, signature: "00".repeat(64) } }),
  // validly signed by the anchor, about a DIFFERENT operation
  "mismatched-operation": write("mismatched-operation.json", {
    request: createApprovalRequest({ ...base, operationDigest: "44".repeat(32) }),
    response: createSignedApprovalResponse({
      challenge: base.challenge,
      signature: nodeSign(null, approvalSigningBytes(createApprovalRequest({ ...base, operationDigest: "44".repeat(32) })), A.privateKey).toString("hex"),
    }),
  }),
  // an UNSIGNED wrapper field claiming a person was present
  "wrapper-claims-attendance": write("wrapper-claims-attendance.json",
    { ...honest, attendance: "human-present", humanApproved: true }),
  // a document that carries its own key, which is not an anchor at all
  "key-from-document": write("key-from-document.json",
    { ...honest, publicKey: A.pkHex }),
  // the signer declining, which is a named outcome rather than a signature
  "refused-by-signer": write("refused-by-signer.json",
    { request, response: createRefusedApprovalResponse({ challenge: request.challenge, refusal: "signer:declined" }) }),
};

writeFileSync(join(OUT, "PROVENANCE.json"), JSON.stringify({
  producer: "aukora-genesis plugins/aukora-aumlok/lib/{owner-approval,owner-signer}.mjs",
  genesisCommit: arg("--genesis-commit"),
  requestDomain: APPROVAL_REQUEST_DOMAIN,
  preimageSha256: createHash("sha256").update(preimage).digest("hex"),
  fixtures: digests,
  keys: { "anchor-a.pk": A.pkHex, "anchor-b.pk": B.pkHex,
          note: "disposable, generated by this run; no custody, no trust" },
  note: "The signed bytes and the response record come from Genesis's contract code; the signature is a standard Ed25519 signature over those bytes.",
}, null, 2) + "\n");
console.log(`wrote ${Object.keys(digests).length} fixtures + 2 anchors to ${OUT}`);
